using System;using System.Text;using System.Linq;using System.Collections.Generic;using System.Globalization;
namespace Frociart {
    // Explicit read-only schema; expensive collections are requested lazily, without reflection.
    internal static class FlowTemplateData {
        internal static string Safe(string name){var b=new StringBuilder();foreach(char ch in name??"")if(ch>='a'&&ch<='z'||ch>='A'&&ch<='Z'||ch>='0'&&ch<='9')b.Append(ch);else b.Append("_u").Append(((int)ch).ToString("x4"));return b.ToString();}
        static FlowCodeTemplate.Deferred Later(Func<object> value){return new FlowCodeTemplate.Deferred(value);}
        static List<object> List<T>(IEnumerable<T> values,Func<T,object> map){return values.Select(map).ToList();}
        internal static FlowCodeTemplate.Data Create(FlowSource.Program program){return new Builder(program).Build();}
        sealed class Builder {
            internal readonly FlowSource.Program Program;internal readonly Dictionary<string,string> Functions=new Dictionary<string,string>();int budget;
            internal Builder(FlowSource.Program program){Program=program;int index=0;foreach(var s in program.Scopes)if(s.Id!=null)Functions.Add(s.Id,"function_"+(index++).ToString(CultureInfo.InvariantCulture)+"_"+Safe(s.Name));}
            internal FlowCodeTemplate.Deferred Later(Func<object> value){if(++budget>32768)throw new ArgumentException("I dati del modello superano il limite. Usa il campo source per il programma completo.");return new FlowCodeTemplate.Deferred(value);}
            internal FlowCodeTemplate.Data Make(FlowSourceText.Origin origin=null){if(++budget>32768)throw new ArgumentException("I dati del modello superano il limite. Usa il campo source per il programma completo.");return new FlowCodeTemplate.Data(origin);}
            internal FlowCodeTemplate.Data Build(){var scopes=List(Program.Scopes,s=>Later(()=>new Scope(this,s).Build()));return Make().Put("schema",1d).Put("title",Program.Title).Put("scopes",scopes).Put("main",scopes[0]).Put("functions",scopes.Skip(1).ToList());}
        }
        sealed class Scope {
            readonly Builder owner;readonly FlowSource.Scope graph;readonly Dictionary<string,FlowCodeTemplate.Deferred> blocks=new Dictionary<string,FlowCodeTemplate.Deferred>();
            readonly Lazy<List<string>> names;readonly Dictionary<string,string> symbols=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
            internal Scope(Builder owner,FlowSource.Scope graph){this.owner=owner;this.graph=graph;names=new Lazy<List<string>>(CollectNames);foreach(var b in graph.Blocks)blocks.Add(b.Id,Later(()=>Block(b)));}
            FlowCodeTemplate.Deferred Later(Func<object> value){return owner.Later(value);}
            List<string> CollectNames(){var result=new List<string>();Action<string> add=name=>{if(name!=null&&!symbols.ContainsKey(name)){symbols.Add(name,"variable_"+result.Count.ToString(CultureInfo.InvariantCulture)+"_"+Safe(name));result.Add(name);}};foreach(var p in graph.Parameters)add(p.Name);foreach(var b in graph.Blocks){var o=b.Operation;if(o.Input!=null){add(o.Input.Name);Collect(o.Input.Index,add);}if(o.Declaration!=null){foreach(string name in o.Declaration.Names)add(name);Collect(o.Declaration.Size,add);}foreach(var w in o.Writes){add(w.Target.Name);Collect(w.Target.Index,add);Collect(w.Value,add);}Collect(o.Value,add);}return result;}
            void Collect(FlowSource.Expression e,Action<string> add){if(e==null)return;if(e.Kind==FlowSource.ExpressionKind.Variable)add(e.Text);foreach(var child in e.Children)Collect(child,add);}
            string Identifier(string name){if(name==null)return "";var initialized=names.Value;string value;if(symbols.TryGetValue(name,out value))return value;throw new ArgumentException("Simbolo del modello non trovato: "+name+".");}
            internal FlowCodeTemplate.Data Build(){var plan=new Lazy<FlowSourcePlan>(()=>FlowSourcePlan.Create(graph));return owner.Make().Put("id",graph.Id??"").Put("key",graph.Id==null?"main":owner.Functions[graph.Id]).Put("name",graph.Name).Put("isMain",graph.Id==null).Put("returns",graph.ReturnType!=FlowDataType.Void).Put("returnType",graph.ReturnType.ToString().ToLowerInvariant()).Put("returnArray",graph.ReturnIsArray).Put("returnVariable",graph.ReturnVariable??"").Put("returnIdentifier",Later(()=>graph.ReturnType==FlowDataType.Void?"":Identifier(graph.ReturnVariable))).Put("start",graph.StartId)
                .Put("symbolNames",Later(()=>names.Value.Cast<object>().ToList())).Put("symbols",Later(()=>List(names.Value,n=>Later(()=>owner.Make().Put("name",n).Put("identifier",Identifier(n))))))
                .Put("parameters",Later(()=>List(graph.Parameters,p=>Later(()=>owner.Make().Put("name",p.Name).Put("identifier",Identifier(p.Name)).Put("type",p.Type.ToString().ToLowerInvariant()).Put("array",p.IsArray).Put("reference",p.ByReference)))))
                .Put("blocks",List(graph.Blocks,b=>blocks[b.Id])).Put("notes",List(graph.Notes,n=>Later(()=>Block(n)))).Put("structured",Later(()=>plan.Value.Structured)).Put("statements",Later(()=>plan.Value.Structured?List(plan.Value.Statements,s=>Later(()=>Statement(s,0))):new List<object>()));}
            FlowCodeTemplate.Data Target(FlowSource.Target target,FlowSourceText.Origin origin){return target==null?null:owner.Make(origin).Put("name",target.Name).Put("identifier",Later(()=>Identifier(target.Name))).Put("indexed",target.Index!=null).Put("index",Later(()=>Expression(target.Index,origin,0)));}
            FlowCodeTemplate.Data Expression(FlowSource.Expression e,FlowSourceText.Origin origin,int depth){if(e==null)return null;if(depth>256)throw new ArgumentException("L’espressione supera la profondità del modello.");return owner.Make(origin).Put("kind",e.Kind.ToString().ToLowerInvariant()).Put("text",e.Text??"").Put("number",e.Number).Put("bits",BitConverter.DoubleToInt64Bits(e.Number).ToString("x16")).Put("boolean",e.Boolean).Put("functionId",e.FunctionId??"").Put("functionKey",e.FunctionId==null?"":owner.Functions[e.FunctionId]).Put("identifier",Later(()=>e.Kind==FlowSource.ExpressionKind.Variable?Identifier(e.Text):""))
                .Put("isNumber",e.Kind==FlowSource.ExpressionKind.Number).Put("isText",e.Kind==FlowSource.ExpressionKind.Text).Put("isBoolean",e.Kind==FlowSource.ExpressionKind.Boolean).Put("isVariable",e.Kind==FlowSource.ExpressionKind.Variable).Put("isVector",e.Kind==FlowSource.ExpressionKind.Vector).Put("isIndex",e.Kind==FlowSource.ExpressionKind.Index).Put("isUnary",e.Kind==FlowSource.ExpressionKind.Unary).Put("isBinary",e.Kind==FlowSource.ExpressionKind.Binary).Put("isCall",e.Kind==FlowSource.ExpressionKind.Call).Put("children",Later(()=>List(e.Children,c=>Later(()=>Expression(c,origin,depth+1)))));}
            FlowCodeTemplate.Data Declaration(FlowSource.Declaration declaration,FlowSourceText.Origin origin){return declaration==null?null:owner.Make(origin).Put("type",declaration.Type.ToString().ToLowerInvariant()).Put("array",declaration.IsArray).Put("size",Later(()=>Expression(declaration.Size,origin,0))).Put("names",List(declaration.Names,n=>Later(()=>owner.Make(origin).Put("name",n).Put("identifier",Later(()=>Identifier(n))))));}
            FlowCodeTemplate.Data Block(FlowSource.Block b){var origin=new FlowSourceText.Origin(graph.Id,b.Id);var o=b.Operation;return owner.Make(origin).Put("id",b.Id).Put("kind",b.Kind.ToString().ToLowerInvariant()).Put("text",b.Text).Put("prompt",b.Prompt??"").Put("comment",b.Comment??"").Put("reachable",b.Reachable)
                .Put("isStart",b.Kind==NodeKind.Start).Put("isEnd",b.Kind==NodeKind.End).Put("isInput",b.Kind==NodeKind.Input).Put("isOutput",b.Kind==NodeKind.Output).Put("isProcess",b.Kind==NodeKind.Process).Put("isDecision",b.Kind==NodeKind.Decision).Put("isDeclare",b.Kind==NodeKind.Declare).Put("isCall",b.Kind==NodeKind.Call).Put("isNote",b.Kind==NodeKind.Note).Put("isPause",b.Kind==NodeKind.Pause)
                .Put("input",Later(()=>Target(o.Input,origin))).Put("value",Later(()=>Expression(o.Value,origin,0))).Put("declaration",Later(()=>Declaration(o.Declaration,origin))).Put("writes",Later(()=>List(o.Writes,w=>Later(()=>owner.Make(origin).Put("target",Later(()=>Target(w.Target,origin))).Put("value",Later(()=>Expression(w.Value,origin,0)))))))
                .Put("links",Later(()=>List(b.Links,l=>Later(()=>owner.Make(origin).Put("id",l.Id).Put("to",l.To).Put("branch",l.Branch))))).Put("next",b.Next("next")??"").Put("yes",b.Next("true")??"").Put("no",b.Next("false")??"").Put("fileReading",o.FileReading).Put("fileNewline",o.FileNewline).Put("turtleDraw",o.TurtleDraw).Put("turtleLeft",o.TurtleLeft).Put("outputNewline",o.OutputNewline);}
            FlowCodeTemplate.Data Statement(FlowSourcePlan.Statement statement,int depth){if(depth>64)throw new ArgumentException("Il piano supera la profondità del modello.");return owner.Make(new FlowSourceText.Origin(graph.Id,statement.Block.Id)).Put("kind",statement.Kind.ToString().ToLowerInvariant()).Put("instruction",statement.Kind==FlowSourcePlan.Kind.Instruction).Put("conditional",statement.Kind==FlowSourcePlan.Kind.If).Put("loop",statement.Kind==FlowSourcePlan.Kind.While||statement.Kind==FlowSourcePlan.Kind.Repeat).Put("postTest",statement.Kind==FlowSourcePlan.Kind.Repeat).Put("entryBlock",blocks[statement.EntryBlock.Id]).Put("loopOnTrue",statement.LoopOnTrue).Put("block",blocks[statement.Block.Id]).Put("body",List(statement.Body,s=>Later(()=>Statement(s,depth+1)))).Put("otherwise",List(statement.Otherwise,s=>Later(()=>Statement(s,depth+1))));}
        }
    }
}
